import {renderView,section,list,button,form,field,textInput,selectInput,textarea} from '../ui/view.js';import {StoryService} from '../services/story-service.js';import {loadJson} from './literary-core-config-loader.js';import {el,formDataObject} from './literary-core-dom.js';import {notify} from './literary-core-notifications.js';
async function entityView(typeFilter,title,description){const [r,types]=await Promise.all([StoryService.entities(typeFilter?{entityType:typeFilter}:{}),loadJson('json/entity-types.json')]);const entities=r.entities||[];const body=document.createDocumentFragment();body.append(section(`Add ${typeFilter||'world entry'}`,[form('',[field('Name',textInput('name',{required:true})),field('Type',selectInput('entityType',types,typeFilter||'location')),field('Aliases',textInput('aliases')),field('Description',textarea('description',{rows:5})),field('Tags',textInput('tags'))],async(fd,f)=>{const d=formDataObject(f);d.aliases=String(d.aliases||'').split(',').map(x=>x.trim()).filter(Boolean);d.tags=String(d.tags||'').split(',').map(x=>x.trim()).filter(Boolean);await StoryService.saveEntity(d);notify('Saved.');entityView(typeFilter,title,description);},{submitLabel:'Save'})]));body.append(section('Entries',[list(entities,e=>{const a=el('article',{},[el('h3',{text:e.name}),el('p',{text:e.description||''}),el('small',{text:(e.aliases||[]).join(', ')})]);a.append(button('Delete',async()=>{await StoryService.deleteEntity(e.id);entityView(typeFilter,title,description);}));return a;},{empty:'No entries yet.'})]));renderView(title,{description,body});}
export const charactersView=()=>entityView('character','Characters','Searchable character profiles connected to aliases, evolving state, relationships, knowledge, and scene presence.');
export const worldView=()=>entityView('','World Codex','Locations, organizations, factions, cultures, species, objects, terminology, technology, magic, and rules stay structured and project-scoped.');
